alter table homework_private.attempts add column submitted_at timestamptz;
create or replace function public.homework_start(p_id uuid,p_lesson text,p_edit_key text,p_read_key text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t jsonb; a homework_private.attempts;
begin
 if p_id is null or p_edit_key is null or p_read_key is null or p_edit_key !~ '^[0-9a-f]{64}$' or p_read_key !~ '^[0-9a-f]{64}$' or p_read_key=p_edit_key then raise exception 'Invalid keys'; end if;
 select definition into t from homework_private.templates where lesson_id=p_lesson and enabled;
 if t is null then raise exception 'Homework unavailable'; end if;
 insert into homework_private.attempts(id,lesson_id,edit_hash,read_hash,definition)
 values(p_id,p_lesson,encode(extensions.digest(p_edit_key,'sha256'),'hex'),encode(extensions.digest(p_read_key,'sha256'),'hex'),t)
 on conflict(id) do nothing;
 select * into a from homework_private.attempts where id=p_id and lesson_id=p_lesson and edit_hash=encode(extensions.digest(p_edit_key,'sha256'),'hex') and read_hash=encode(extensions.digest(p_read_key,'sha256'),'hex');
 if a.id is null then raise exception 'Work unavailable'; end if;
 return jsonb_build_object('id',a.id,'definition',a.definition,'answers',a.answers,'revision',a.revision,'updated_at',a.updated_at,'submitted_at',a.submitted_at);
end; $$;
create or replace function public.homework_read(p_id uuid,p_key text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare a homework_private.attempts; h text;
begin
 if p_key is null or p_key !~ '^[0-9a-f]{64}$' then raise exception 'Work unavailable'; end if;
 h:=encode(extensions.digest(p_key,'sha256'),'hex');
 select * into a from homework_private.attempts where id=p_id and (read_hash=h or edit_hash=h);
 if a.id is null then raise exception 'Work unavailable'; end if;
 return jsonb_build_object('id',a.id,'definition',a.definition,'answers',a.answers,'revision',a.revision,'updated_at',a.updated_at,'submitted_at',a.submitted_at);
end; $$;
create or replace function public.homework_save(p_id uuid,p_edit_key text,p_revision integer,p_answers jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a homework_private.attempts;
begin
 if p_edit_key is null or p_edit_key !~ '^[0-9a-f]{64}$' or p_answers is null or jsonb_typeof(p_answers)<>'object' or octet_length(p_answers::text)>131072 then raise exception 'Invalid work'; end if;
 select * into a from homework_private.attempts where id=p_id and edit_hash=encode(extensions.digest(p_edit_key,'sha256'),'hex') for update;
 if a.id is null then raise exception 'Work unavailable'; end if;
 if a.submitted_at is not null then raise exception 'Work submitted'; end if;
 if p_revision is distinct from a.revision then raise exception 'Revision conflict'; end if;
 update homework_private.attempts set answers=p_answers,revision=revision+1,updated_at=now() where id=p_id returning * into a;
 return jsonb_build_object('revision',a.revision,'updated_at',a.updated_at,'submitted_at',a.submitted_at);
end; $$;

create function public.homework_submit(p_id uuid,p_edit_key text,p_revision integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a homework_private.attempts;
begin
 if p_edit_key is null or p_edit_key !~ '^[0-9a-f]{64}$' then raise exception 'Work unavailable'; end if;
 select * into a from homework_private.attempts where id=p_id and edit_hash=encode(extensions.digest(p_edit_key,'sha256'),'hex') for update;
 if a.id is null then raise exception 'Work unavailable'; end if;
 if a.submitted_at is not null then return jsonb_build_object('revision',a.revision,'submitted_at',a.submitted_at); end if;
 if p_revision is distinct from a.revision then raise exception 'Revision conflict'; end if;
 update homework_private.attempts set submitted_at=now(),updated_at=now(),revision=revision+1 where id=p_id returning * into a;
 return jsonb_build_object('revision',a.revision,'submitted_at',a.submitted_at);
end; $$;
revoke all on function public.homework_submit(uuid,text,integer) from public;
grant execute on function public.homework_submit(uuid,text,integer) to anon,authenticated;
