insert into homework_private.templates(lesson_id,definition) values ('a1-2-w4-l4','{"id":"a1-2-w4-l4","version":"20261004-2","level":"A1.2","title":"Сосед","steps":[{"role":"words","exercise":{"version":1,"id":"L4-word-translation","kind":"matching","title":"Соедините картинки и слова.","layout":"picture-word","items":[{"id":"1","text":"1","alt":"Картинка 1","correctId":"o0","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/polite.webp","imageWidth":480,"imageHeight":600},{"id":"2","text":"2","alt":"Картинка 2","correctId":"o1","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/rude.webp","imageWidth":480,"imageHeight":600},{"id":"3","text":"3","alt":"Картинка 3","correctId":"o2","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/helpful.webp","imageWidth":480,"imageHeight":600},{"id":"4","text":"4","alt":"Картинка 4","correctId":"o3","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/lazy.webp","imageWidth":480,"imageHeight":600},{"id":"5","text":"5","alt":"Картинка 5","correctId":"o4","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/quiet.webp","imageWidth":480,"imageHeight":600},{"id":"6","text":"6","alt":"Картинка 6","correctId":"o5","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/noisy.webp","imageWidth":480,"imageHeight":600}],"options":[{"id":"o3","text":"lazy"},{"id":"o5","text":"noisy"},{"id":"o0","text":"polite"},{"id":"o4","text":"quiet"},{"id":"o1","text":"rude"},{"id":"o2","text":"helpful"}]}},{"role":"listenRepeat","exercise":{"version":1,"id":"L4-M03","kind":"audio","title":"Listen and repeat.","layout":"listen-repeat","audioPending":false,"items":[{"id":"L4-W01","text":"polite","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W01.mp3?v=20261003-sarah-slow1-r3","example":"My father is very polite.","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W01-example.mp3?v=20261003-sarah-slow1-r3"},{"id":"L4-W02","text":"rude","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W02.mp3?v=20261003-sarah-slow1-r3","example":"This man is rude.","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W02-example.mp3?v=20261003-sarah-slow1-r3"},{"id":"L4-W03","text":"helpful","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W03.mp3?v=20261003-sarah-slow1-r3","example":"My children are very helpful.","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W03-example.mp3?v=20261003-sarah-slow1-r3"},{"id":"L4-W04","text":"lazy","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W04.mp3?v=20261003-sarah-slow1-r3","example":"I’m sometimes lazy on weekends.","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W04-example.mp3?v=20261003-sarah-slow1-r3"},{"id":"L4-W05","text":"quiet","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W05.mp3?v=20261003-sarah-slow1-r3","example":"My sister is usually quiet.","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W05-example.mp3?v=20261003-sarah-slow1-r3"},{"id":"L4-W06","text":"noisy","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W06.mp3?v=20261003-sarah-slow1-r3","example":"Our neighbors are noisy at night.","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l4/listen-repeat/L4-W06-example.mp3?v=20261003-sarah-slow1-r3"}]}},{"role":"practice","exercise":{"version":1,"id":"L4-question-answer-match","kind":"matching","title":"Match the questions with the answers.","items":[{"id":"1","text":"What is he like?","correctId":"o0"},{"id":"2","text":"What does she look like?","correctId":"o1"},{"id":"3","text":"What does he look like?","correctId":"o2"},{"id":"4","text":"What is she like?","correctId":"o3"}],"options":[{"id":"o1","text":"Her hair is short and curly."},{"id":"o0","text":"He’s a little lazy at home."},{"id":"o3","text":"She’s helpful. She often helps me with my homework."},{"id":"o2","text":"He has long straight hair."}]}},{"role":"rule","exercise":{"version":1,"id":"L4-question-rule-homework-rule","kind":"rule-page","title":"Как спросить о человеке","blocks":[{"type":"rule","text":"В английском языке вопросы What is he/she like? и What does he/she look like? используются, когда мы хотим узнать разную информацию о человеке.\n\n1. What is he/she like?\n\nИспользуйте What is he/she like?, чтобы спросить, какой человек по характеру или поведению.\n\nWhat is she like? — Какая она?\nShe is polite and helpful. — Она вежливая и готовая помочь.\n\nВ ответе используйте be + adjective:\n\nHe is quiet.\nShe is rude.\n\n2. What does he/she look like?\n\nИспользуйте What does he/she look like?, чтобы спросить, как человек выглядит.\n\nWhat does she look like? — Как она выглядит?\nShe has long brown hair. — У неё длинные каштановые волосы.\n\nДля описания внешности можно использовать have/has + noun:\n\nHe has short straight hair.\nShe has long curly hair.\n\n3. What does he/she like?\n\nНе путайте What is she like? и What does she like?\n\nWhat does she like? означает «Что ей нравится?»\n\nWhat does she like? — Что ей нравится?\nShe likes music. — Ей нравится музыка.","highlights":["What is he/she like?","What does he/she look like?","What does he/she like?","What is she like?","What does she look like?","What does she like?","be + adjective","have/has + noun"]}]}},{"role":"translation","exercise":{"version":1,"id":"L4-homework-1","kind":"writing","title":"Translate into English.","responseMode":"accepted","revealPossibleAnswers":false,"instruction":"Переведите вопросы и ответы на английский.","items":[{"id":"1","prompt":"Какой Джейк?","placeholder":"Jake","acceptedAnswers":["What is Jake like?","What is Jake like","What''s Jake like?","What''s Jake like","What’s Jake like?","What’s Jake like"]},{"id":"2","prompt":"Джейк грубый и шумный.","placeholder":"Jake","acceptedAnswers":["Jake is rude and noisy.","Jake is rude and noisy","He is rude and noisy.","He is rude and noisy","He''s rude and noisy.","He''s rude and noisy","He’s rude and noisy.","He’s rude and noisy"]},{"id":"3","prompt":"Как выглядит Нора?","placeholder":"Nora","acceptedAnswers":["What does Nora look like?","What does Nora look like"]},{"id":"4","prompt":"У Норы длинные каштановые волосы.","placeholder":"Nora","acceptedAnswers":["Nora has long brown hair.","Nora has long brown hair","She has long brown hair.","She has long brown hair"]},{"id":"5","prompt":"Какая Эмма?","placeholder":"Emma","acceptedAnswers":["What is Emma like?","What is Emma like","What''s Emma like?","What''s Emma like","What’s Emma like?","What’s Emma like"]},{"id":"6","prompt":"Эмма вежливая и готовая помочь.","placeholder":"Emma","acceptedAnswers":["Emma is polite and helpful.","Emma is polite and helpful","She is polite and helpful.","She is polite and helpful","She''s polite and helpful.","She''s polite and helpful","She’s polite and helpful.","She’s polite and helpful"]}]}},{"role":"translation","exercise":{"version":1,"id":"L4-homework-2","kind":"writing","title":"Translate into English.","responseMode":"accepted","revealPossibleAnswers":false,"instruction":"Переведите вопросы и ответы на английский.","items":[{"id":"1","prompt":"Как выглядит Бен?","placeholder":"Ben","acceptedAnswers":["What does Ben look like?","What does Ben look like"]},{"id":"2","prompt":"У Бена короткие светлые волосы.","placeholder":"Ben","acceptedAnswers":["Ben has short blonde hair.","Ben has short blonde hair","He has short blonde hair.","He has short blonde hair"]},{"id":"3","prompt":"Какая Лили?","placeholder":"Lily","acceptedAnswers":["What is Lily like?","What is Lily like","What''s Lily like?","What''s Lily like","What’s Lily like?","What’s Lily like"]},{"id":"4","prompt":"Лили тихая.","placeholder":"Lily","acceptedAnswers":["Lily is quiet.","Lily is quiet","She is quiet.","She is quiet","She''s quiet.","She''s quiet","She’s quiet.","She’s quiet"]},{"id":"5","prompt":"Какой Макс?","placeholder":"Max","acceptedAnswers":["What is Max like?","What is Max like","What''s Max like?","What''s Max like","What’s Max like?","What’s Max like"]},{"id":"6","prompt":"Макс ленивый.","placeholder":"Max","acceptedAnswers":["Max is lazy.","Max is lazy","He is lazy.","He is lazy","He''s lazy.","He''s lazy","He’s lazy.","He’s lazy"]}]}}],"reference":{"version":1,"id":"L4-question-rule-homework-rule","kind":"rule-page","title":"Как спросить о человеке","blocks":[{"type":"rule","text":"В английском языке вопросы What is he/she like? и What does he/she look like? используются, когда мы хотим узнать разную информацию о человеке.\n\n1. What is he/she like?\n\nИспользуйте What is he/she like?, чтобы спросить, какой человек по характеру или поведению.\n\nWhat is she like? — Какая она?\nShe is polite and helpful. — Она вежливая и готовая помочь.\n\nВ ответе используйте be + adjective:\n\nHe is quiet.\nShe is rude.\n\n2. What does he/she look like?\n\nИспользуйте What does he/she look like?, чтобы спросить, как человек выглядит.\n\nWhat does she look like? — Как она выглядит?\nShe has long brown hair. — У неё длинные каштановые волосы.\n\nДля описания внешности можно использовать have/has + noun:\n\nHe has short straight hair.\nShe has long curly hair.\n\n3. What does he/she like?\n\nНе путайте What is she like? и What does she like?\n\nWhat does she like? означает «Что ей нравится?»\n\nWhat does she like? — Что ей нравится?\nShe likes music. — Ей нравится музыка.","highlights":["What is he/she like?","What does he/she look like?","What does he/she like?","What is she like?","What does she look like?","What does she like?","be + adjective","have/has + noun"]}]},"exercises":[{"version":1,"id":"L4-word-translation","kind":"matching","title":"Соедините картинки и слова.","layout":"picture-word","items":[{"id":"1","text":"1","alt":"Картинка 1","correctId":"o0","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/polite.webp","imageWidth":480,"imageHeight":600},{"id":"2","text":"2","alt":"Картинка 2","correctId":"o1","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/rude.webp","imageWidth":480,"imageHeight":600},{"id":"3","text":"3","alt":"Картинка 3","correctId":"o2","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/helpful.webp","imageWidth":480,"imageHeight":600},{"id":"4","text":"4","alt":"Картинка 4","correctId":"o3","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/lazy.webp","imageWidth":480,"imageHeight":600},{"id":"5","text":"5","alt":"Картинка 5","correctId":"o4","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/quiet.webp","imageWidth":480,"imageHeight":600},{"id":"6","text":"6","alt":"Картинка 6","correctId":"o5","image":"assets/lesson-media/a1-2/module-4/lesson-4/word-pick/noisy.webp","imageWidth":480,"imageHeight":600}],"options":[{"id":"o3","text":"lazy"},{"id":"o5","text":"noisy"},{"id":"o0","text":"polite"},{"id":"o4","text":"quiet"},{"id":"o1","text":"rude"},{"id":"o2","text":"helpful"}]},{"version":1,"id":"L4-question-answer-match","kind":"matching","title":"Match the questions with the answers.","items":[{"id":"1","text":"What is he like?","correctId":"o0"},{"id":"2","text":"What does she look like?","correctId":"o1"},{"id":"3","text":"What does he look like?","correctId":"o2"},{"id":"4","text":"What is she like?","correctId":"o3"}],"options":[{"id":"o1","text":"Her hair is short and curly."},{"id":"o0","text":"He’s 